-- Création de la base de données
CREATE DATABASE budbud;

-- Connexion à la base
\c budbud;

-- Table des équipes
CREATE TABLE equipes (
    id SERIAL PRIMARY KEY,
    nom VARCHAR(100) NOT NULL,
    active BOOLEAN DEFAULT TRUE
);

-- Table des types de repêchage
CREATE TABLE types_repechage (
    id SERIAL PRIMARY KEY,
    nom VARCHAR(100) NOT NULL
);

-- Table des repêchages
CREATE TABLE repechages (
    id SERIAL PRIMARY KEY,
    annee INT NOT NULL,
    type_id INT REFERENCES types_repechage(id),
    equipe_id INT REFERENCES equipes(id),
    joueur VARCHAR(100) NOT NULL,
    rang INT NOT NULL,
    round INT NUll 
);

-- Table des échanges
CREATE TABLE echanges (
    id SERIAL PRIMARY KEY,
    date DATE NOT NULL,
    equipe_source_id INT REFERENCES equipes(id),
    equipe_destination_id INT REFERENCES equipes(id),
    details TEXT
);

-- Table des trophées
CREATE TABLE trophees (
    id SERIAL PRIMARY KEY,
    nom VARCHAR(100) NOT NULL
);

-- Table des gagnants de trophées
CREATE TABLE trophee_gagnants (
    id SERIAL PRIMARY KEY,
    trophee_id INT REFERENCES trophees(id),
    annee INT NOT NULL,
    equipe_id INT REFERENCES equipes(id),
    joueur VARCHAR(100)
);

